+.footer{ padding: 2.6rem 0 2.2rem; border-top: 1px solid rgba(255,255,255,.08); margin-top: 2.4rem; }
+.footer-grid{ display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }
+.footer h4{ margin: 0 0 .55rem; font-size: .95rem; color: rgba(255,255,255,.82); }
+.footer a{ display:inline-block; padding: .22rem 0; color: rgba(255,255,255,.66); font-size: .92rem; }
+.footer a:hover{ color: rgba(255,255,255,.86); }
+.footer-bottom{ margin-top: 1.6rem; display:flex; align-items:center; justify-content: space-between; flex-wrap: wrap; gap: .75rem; color: rgba(255,255,255,.54); font-size: .9rem; }
+
+/* Mobile */
+.mobile-nav{
+  display: none;
+  position: absolute;
+  top: 62px;
+  right: 0;
+  left: 0;
+  border-bottom: 1px solid rgba(255,255,255,.08);
